logger.message:
#[output application/json --- {
	"message": "Before invoking the GET request from IDP on document action " ++ (lower(vars.doc.actionName)),
	"fileName": vars.document.fileName
}]

#[output application/json --- {
	"message": "After invoking the GET request from IDP on document action " ++ (lower(vars.doc.actionName)),
	"fileName": vars.document.fileName
}]

#[output application/json --- {
	"message": "Before invoking the POST request from IDP on document action " ++ (lower(vars.doc.actionName)),
	"fileName": vars.document.fileName
}]

#[output application/json --- {
	"message": "After invoking the POST request from IDP on document action " ++ (lower(vars.doc.actionName)),
	"fileName": vars.document.fileName
}]

#[output application/json --- {
	"message": "Request sent to fetch the " ++ vars.object ++ " data from salesforce",
	("contentDocumentId": vars.document.contentDocumentId) if(!isEmpty(vars.document.contentDocumentId)),
	("fileName": vars.document.fileName) if(!isEmpty(vars.document.fileName))
}]

#[output application/json --- {
	"message": "Response received for " ++ vars.object ++ " data from salesforce"
}]

#[output application/json --- {
	"message": "Request sent to create record in " ++ vars.object ++  if(vars.object != "Task") (" for " ++ lower(vars.doc.documentType)) else "",
	("contentDocumentId": vars.document.contentDocumentId) if(vars.object != "Task"),
	("fileName": vars.document.fileName) if(vars.object != "Task")
}]

#[output application/json --- {
	"message": "Response received after creation of the record in " ++ vars.object  ++ if(vars.object != "Task") (" for " ++ lower(vars.doc.documentType)) else ""
}]

#[output application/json --- {
	"message": "Response received for " ++ vars.objectName  ++ " status updated from salesforce"
}]
